import type { ToolRunner } from "@bithumb-official/bithumb-core";
import type { CliValues } from "../parser.js";
import { toNumber, toArray, parseJsonStringArray, parseRangedInt, parsePositiveInt, parseEnumString } from "../parser.js";
import { outputLine, errorLine, printJson, printTable, printKv } from "../formatter.js";

// Valid --state values for /v1/withdraws and /v1/withdraws/krw (case-sensitive).
// Bithumb's server expects British spelling CANCELLED (the OpenAPI doc's CANCELED is rejected).
const WITHDRAW_STATES = ["PROCESSING", "DONE", "CANCELLED"] as const;

export async function handleWithdrawCommand(
  run: ToolRunner,
  action: string,
  v: CliValues,
  json: boolean,
): Promise<void> {
  switch (action) {
    case "chance":
      return cmdChance(run, v, json);
    case "get":
      return cmdGet(run, v, json);
    case "list":
      return cmdList(run, v, json);
    case "list-krw":
      return cmdListKrw(run, v, json);
    case "coin":
      return cmdCoin(run, v, json);
    case "krw":
      return cmdKrw(run, v, json);
    case "cancel":
      return cmdCancel(run, v, json);
    case "addresses":
      return cmdAddresses(run, json);
    default:
      errorLine(`Unknown withdraw command: ${action}. Run 'bithumb withdraw --help' for usage.`);
      process.exitCode = 1;
  }
}

async function cmdChance(run: ToolRunner, v: CliValues, json: boolean): Promise<void> {
  if (!v.currency || !v.netType) {
    errorLine("Error: --currency and --net-type required. Example: bithumb withdraw chance --currency BTC --net-type BTC");
    process.exitCode = 1;
    return;
  }
  const result = await run("withdraw_get_chance", { currency: v.currency, net_type: v.netType });
  const data = result.data as Record<string, unknown>;
  if (json) return printJson(data);
  printKv(data);
}

async function cmdGet(run: ToolRunner, v: CliValues, json: boolean): Promise<void> {
  if (!v.currency) {
    errorLine("Error: --currency required. Example: bithumb withdraw get --currency BTC --withdrawal-id abc-123");
    process.exitCode = 1;
    return;
  }
  // Per Bithumb GET /v1/withdraw, only `currency` is required; withdrawal_id and
  // txid are both optional and may be combined (the API treats them as an AND
  // filter). Omitting both returns the most recent withdrawal.
  // Single lookup takes a string `--txid` (quote values containing spaces/commas,
  // e.g. --txid "2025-07-31 15:12:24.407715"). `--txids` (JSON array) is for
  // `withdraw list`, not here.
  const args: Record<string, unknown> = { currency: v.currency };
  if (v.withdrawalId) args.withdrawal_id = v.withdrawalId;
  if (v.txid) args.txid = v.txid;
  const result = await run("withdraw_get", args);
  const data = result.data as Record<string, unknown>;
  if (json) return printJson(data);
  // Relabel the response's legacy `uuid` field as `withdrawal_id` for display
  // consistency with the input flag. Raw JSON (--json) keeps the original field.
  printKv(renameKey(data, "uuid", "withdrawal_id"));
}

async function cmdList(run: ToolRunner, v: CliValues, json: boolean): Promise<void> {
  const args: Record<string, unknown> = {};
  if (v.currency) args.currency = v.currency;
  if (v.state) args.state = parseEnumString("state", v.state, WITHDRAW_STATES);
  if (v.withdrawalIds) args.withdrawal_ids = toArray(v.withdrawalIds);
  if (v.txids) args.txids = parseJsonStringArray("txids", v.txids);
  if (v.limit) args.limit = parseRangedInt("limit", toNumber(v.limit, "limit"), 1, 100);
  if (v.page) args.page = parsePositiveInt("page", toNumber(v.page, "page"));
  if (v.orderBy) args.order_by = v.orderBy;
  const result = await run("withdraw_get_list", args);
  const items = result.data as Record<string, unknown>[];
  if (json) return printJson(items);
  if (!items?.length) { outputLine("No withdrawals found"); return; }
  printTable(items.map((o) => renameKey(o, "uuid", "withdrawal_id")));
}

async function cmdListKrw(run: ToolRunner, v: CliValues, json: boolean): Promise<void> {
  const args: Record<string, unknown> = {};
  if (v.state) args.state = parseEnumString("state", v.state, WITHDRAW_STATES);
  if (v.withdrawalIds) args.withdrawal_ids = toArray(v.withdrawalIds);
  if (v.txids) args.txids = parseJsonStringArray("txids", v.txids);
  if (v.limit) args.limit = parseRangedInt("limit", toNumber(v.limit, "limit"), 1, 100);
  if (v.page) args.page = parsePositiveInt("page", toNumber(v.page, "page"));
  if (v.orderBy) args.order_by = v.orderBy;
  const result = await run("withdraw_get_list_krw", args);
  const items = result.data as Record<string, unknown>[];
  if (json) return printJson(items);
  if (!items?.length) { outputLine("No KRW withdrawals found"); return; }
  printTable(items.map((o) => renameKey(o, "uuid", "withdrawal_id")));
}

// Return a shallow copy of `obj` with key `from` renamed to `to`, preserving
// insertion order. If `from` is absent, returns the object unchanged.
function renameKey(
  obj: Record<string, unknown>,
  from: string,
  to: string,
): Record<string, unknown> {
  if (!(from in obj)) return obj;
  const out: Record<string, unknown> = {};
  for (const [k, val] of Object.entries(obj)) {
    out[k === from ? to : k] = val;
  }
  return out;
}

async function cmdCoin(run: ToolRunner, v: CliValues, json: boolean): Promise<void> {
  if (!v.currency || !v.netType || !v.amount || !v.address) {
    errorLine("Error: --currency, --net-type, --amount, --address required.");
    errorLine("CAUTION: This will initiate a real cryptocurrency withdrawal!");
    process.exitCode = 1;
    return;
  }
  const args: Record<string, unknown> = {
    currency: v.currency,
    net_type: v.netType,
    amount: v.amount,
    address: v.address,
  };
  if (v.secondaryAddress) args.secondary_address = v.secondaryAddress;
  if (v.exchangeName) args.exchange_name = v.exchangeName;
  if (v.receiverType) args.receiver_type = v.receiverType;
  if (v.receiverKoName) args.receiver_ko_name = v.receiverKoName;
  if (v.receiverEnName) args.receiver_en_name = v.receiverEnName;
  if (v.receiverCorpKoName) args.receiver_corp_ko_name = v.receiverCorpKoName;
  if (v.receiverCorpEnName) args.receiver_corp_en_name = v.receiverCorpEnName;
  const result = await run("withdraw_coin", args);
  const data = result.data as Record<string, unknown>;
  if (json) return printJson(data);
  printKv(data);
}

async function cmdKrw(run: ToolRunner, v: CliValues, json: boolean): Promise<void> {
  if (!v.amount || !v.twoFactorType) {
    errorLine("Error: --amount and --two-factor-type required.");
    errorLine("CAUTION: This will initiate a real KRW withdrawal!");
    process.exitCode = 1;
    return;
  }
  const result = await run("withdraw_krw", { amount: v.amount, two_factor_type: v.twoFactorType });
  const data = result.data as Record<string, unknown>;
  if (json) return printJson(data);
  printKv(data);
}

async function cmdCancel(run: ToolRunner, v: CliValues, json: boolean): Promise<void> {
  if (!v.withdrawalId) {
    errorLine("Error: --withdrawal-id required. Example: bithumb withdraw cancel --withdrawal-id abc-123");
    process.exitCode = 1;
    return;
  }
  const result = await run("withdraw_cancel_coin", { withdrawal_id: v.withdrawalId });
  const data = result.data as Record<string, unknown>;
  if (json) return printJson(data);
  printKv(data);
}

async function cmdAddresses(run: ToolRunner, json: boolean): Promise<void> {
  const result = await run("withdraw_get_addresses", {});
  const items = result.data as Record<string, unknown>[];
  if (json) return printJson(items);
  if (!items?.length) { outputLine("No withdrawal addresses found"); return; }
  printTable(items);
}
